export const LINES: Line[] = [
 {
  "id": "L01",
  "file": "L01",
  "text": "Every group trip has one friend who books the place, and then spends weeks chasing everyone for the money.",
  "from": 15,
  "to": 205,
  "start": 0.5,
  "dur": 6.32
 },
 {
  "id": "L02",
  "file": "L02",
  "text": "So we built Dibs, where the trip itself is a contract on NEAR. Every bed gets its own account with no keys, and nobody can book until every bed is paid.",
  "from": 228,
  "to": 547,
  "start": 7.6,
  "dur": 10.64
 },
 {
  "id": "L03",
  "file": "L03W",
  "text": "Now Leo pays for his bed. He claims it with his own wallet, or with a passkey if he has none. He pays with USDC on Base, NEAR Intents swaps it, and it lands in bed three.",
  "from": 570,
  "to": 966,
  "start": 19.0,
  "dur": 13.2
 },
 {
  "id": "L03A",
  "file": "L03A",
  "text": "We ran this same payment on NEAR mainnet, with real money.",
  "from": 946,
  "to": 1079,
  "start": 31.55,
  "dur": 4.41
 },
 {
  "id": "L04",
  "file": "L04",
  "text": "Say Ana can't make it anymore. She asks for a refund, and the contract refuses, because that would leave the trip short. So she sells her bed at face value to Priya, who's already waiting with her money in.",
  "from": 1164,
  "to": 1555,
  "start": 38.8,
  "dur": 13.04
 },
 {
  "id": "L05",
  "file": "L05",
  "text": "Once all eight beds are paid, OutLayer's verifiable randomness decides who sleeps where, so nobody argues over the double room.",
  "from": 1581,
  "to": 1816,
  "start": 52.7,
  "dur": 7.84
 },
 {
  "id": "L06",
  "file": "L06",
  "text": "Now Maya books, but not with her own money. An OutLayer enclave, called from NEAR, issues the trip its own card, sealed to Maya's passkey, and it only works at hotels. So the hotel charge goes through, and the electronics store is declined. For now, that card runs on Lithic's sandbox.",
  "from": 1842,
  "to": 2432,
  "start": 61.4,
  "dur": 19.68
 },
 {
  "id": "L07",
  "file": "L07",
  "text": "Here's a real booking.com confirmation from one of our own trips, landing in that trip's own inbox. An Intel TDX enclave checks that booking.com really signed it, and NEAR AI reads it privately, so friends only see the dates, the guests and the total. When the contract verifies that signed result on chain, the crew's DAO releases the money on its own.",
  "from": 2463,
  "to": 3185,
  "start": 82.1,
  "dur": 24.08
 },
 {
  "id": "L08",
  "file": "L08",
  "text": "If someone forges that email, the contract refuses it. We threw thirty-five attacks at the contracts, and every one was refused.",
  "from": 3213,
  "to": 3477,
  "start": 107.1,
  "dur": 8.8
 },
 {
  "id": "L09",
  "file": "L09",
  "text": "So nobody fronts the money, and nobody has to chase anyone. The Lisbon trip is live on NEAR testnet, and the link is right below.",
  "from": 3501,
  "to": 3758,
  "start": 116.7,
  "dur": 8.56
 }
];
